export const getCreateBookingMockHandler = (
  overrideResponse?:
    | Booking
    | ((
        info: Parameters<HttpResponseResolver<PathParams, CreateBookingRequest>>[0],
      ) => Promise<Booking> | Booking),
  options?: RequestHandlerOptions,
) => {
  return http.post<PathParams, CreateBookingRequest>(
    "*/bookings",
    async (info: Parameters<HttpResponseResolver<PathParams, CreateBookingRequest>>[0]) => {
      await delay(150);

      return HttpResponse.json(
        overrideResponse !== undefined
          ? typeof overrideResponse === "function"
            ? await overrideResponse(info)
            : overrideResponse
          : getCreateBookingResponseMock(),
        { status: 201 },
      );
    },
    options,
  );
};

